-- Read-only catalog and aggregate preflight. No customer identifiers or secrets.
BEGIN READ ONLY;
SELECT jsonb_build_object(
 'captured_at', now(),
 'migrations',(SELECT jsonb_agg(jsonb_build_object('version',version,'name',name) ORDER BY version) FROM supabase_migrations.schema_migrations),
 'columns',(SELECT jsonb_agg(jsonb_build_object('table',table_name,'column',column_name,'nullable',is_nullable)) FROM information_schema.columns WHERE table_schema='public' AND (table_name='workspace_settings' AND column_name IN ('logo_path','cover_path','discovery_enabled') OR table_name='professional_profiles' AND column_name='photo_path' OR table_name='profiles' AND column_name IN ('avatar_path','residence_city'))),
 'relations',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'rls',c.relrowsecurity,'forced',c.relforcerowsecurity)) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.relkind='r' AND n.nspname IN ('public','app')),
 'functions',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'arguments',pg_get_function_identity_arguments(p.oid),'definer',p.prosecdef,'config',p.proconfig,'anon',has_function_privilege('anon',p.oid,'EXECUTE'),'authenticated',has_function_privilege('authenticated',p.oid,'EXECUTE'),'service_role',has_function_privilege('service_role',p.oid,'EXECUTE'),'definition_md5',md5(pg_get_functiondef(p.oid)),'definition',pg_get_functiondef(p.oid))) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN ('app','public') AND p.proname IN ('create_public_appointment','create_appointment','update_workspace_settings','require_confirmed_email','require_workspace_manager','can_write_appointment','resolve_public_workspace','discovery_text','search_public_workspaces','get_appointment_whatsapp','get_related_client_avatar','get_professional_photo','queue_professional_photo','swap_professional_photo','claim_professional_photo_cleanup','finish_professional_photo_cleanup','require_professional_photo_editor','queue_workspace_image_upload','swap_workspace_image','claim_workspace_image_cleanup','finish_workspace_image_cleanup','get_public_workspace_cover')),
 'storage_policies',(SELECT jsonb_agg(to_jsonb(p)) FROM pg_policies p WHERE schemaname='storage' AND tablename='objects'),
 'buckets',(SELECT jsonb_agg(jsonb_build_object('id',id,'public',public,'limit',file_size_limit,'mime',allowed_mime_types)) FROM storage.buckets),
 'object_counts',(SELECT jsonb_agg(to_jsonb(c)) FROM (SELECT bucket_id,count(*) objects FROM storage.objects GROUP BY bucket_id) c),
 'discovery_index',(SELECT indexdef FROM pg_indexes WHERE schemaname='public' AND indexname='workspace_settings_discovery_city'),
 'compatibility',jsonb_build_object('workspaces',(SELECT count(*) FROM public.workspaces),'appointments',(SELECT count(*) FROM public.appointments),'linked_clients',(SELECT count(*) FROM public.workspace_clients WHERE linked_user_id IS NOT NULL),'legacy_logo_paths',(SELECT count(*) FROM public.workspace_settings WHERE logo_path IS NOT NULL),'invalid_logo_ownership',(SELECT count(*) FROM public.workspace_settings WHERE logo_path IS NOT NULL AND logo_path NOT LIKE workspace_id::text||'/%'),'future_bookings',(SELECT count(*) FROM public.appointments WHERE starts_at>now() AND status IN ('scheduled','confirmed')))
) AS audit;
COMMIT;
